#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long x, y;

long long exp_mod(long long a, long long e) {
    if (e == 0) return 1;
    if (e == 1) return a % MOD;
    long long r = exp_mod(a, e >> 1);
    r = (r * r) % MOD;
    if (e & 1) r = (r * a) % MOD;
    return r;
}

long long gcdExt(long long a, long long b, long long &x, long long &y) {
    if (a == 0) {
        x = 0; y = 1;
        return b;
    }
    long long x1, y1;
    long long gcd = gcdExt(b % a, a, x1, y1);
    x = y1 - (b / a) * x1;
    y = x1;
    return gcd;
}

long long inv(long long a, long long b) {
    x = 0; y = 1;
    gcdExt(a, b, x, y);
    return (x % b + b) % b;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n; long long k;
    cin >> n >> k;
    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }
    vector<long long> fact(n + 1, 1), inv_fact(n + 1, 1);
    for (int i = 1; i <= n; i++) {
        fact[i] = (i * fact[i - 1]) % MOD;
        inv_fact[i] = inv(fact[i], MOD);
    }
    int r = (int)(n - k);
    long long ways = 0;
    for (int i = 1; i <= r; i++) {
        long long l = fact[r] * inv_fact[r - i] % MOD;
        l = l * inv_fact[i] % MOD;
        l = l * exp_mod(i, n) % MOD;
        if ((r - i) % 2 == 1) l = -l;
        ways = (ways + l + MOD) % MOD;
    }
    if (k == 0) {
        long long res = ways * fact[n] % MOD;
        res = res * inv_fact[r] % MOD;
        res = res * inv_fact[n - r] % MOD;
        cout << res << "\n";
    } else {
        long long res = 2 * ways % MOD;
        res = res * fact[n] % MOD;
        res = res * inv_fact[r] % MOD;
        res = res * inv_fact[n - r] % MOD;
        cout << res << "\n";
    }
    return 0;
}

